traj_localization.sourceCode:
// Lichtblick's 3D panel cannot render nav_msgs/Odometry: there is no ODOMETRY
// entry in ThreeDeeRender/ros.ts and no renderable handles it, so an odometry
// topic configured under "topics" is silently ignored. Converting to
// nav_msgs/Path here is what puts the trajectory on screen -- the 3D panel does
// render Path (PoseArrays.ts, default display type "line").
//
// Use Message<"schema/name"> from "./types", NOT the Messages.* namespace from
// the ros lib: ast.ts resolves a return type declared in generatedTypes.ts back
// to the property-signature key, which is how the output topic gets the real
// datatype "nav_msgs/msg/Path". Keep the ROS 2 "msg" segment -- this bag records
// nav_msgs/msg/Path, not nav_msgs/Path.
//
// Getting either wrong fails silently: the script is dropped from the
// registration list, /studio_script/* never appears in the 3D panel's topic
// list, and the diagnostic goes to the User Scripts panel -- which an embedded
// single-3D-panel layout does not contain.
import { Input, Message } from "./types";

export const inputs = ["/odom/localization_odom"];
export const output = "/studio_script/traj_localization";

// The trail is kept in module scope: the script is invoked once per message and
// only the return value reaches the panel, so accumulation has to live out here.
// Typed off the Path schema itself so this depends on one schema name, not on
// geometry_msgs/msg/PoseStamped also being registered by the data source.
const poses: Message<"nav_msgs/msg/Path">["poses"] = [];
const MAX_POSES = 3000;

export default function script(event: Input<"/odom/localization_odom">): Message<"nav_msgs/msg/Path"> {
  poses.push({ header: event.message.header, pose: event.message.pose.pose });
  if (poses.length > MAX_POSES) {
    poses.shift();
  }
  return { header: event.message.header, poses };
}

